#include <stdio.h>
#include <stdbool.h>

struct Point {
    int x;
    int y;
};

bool point_equal(struct Point a, struct Point b) {   /* member by member. */
    return a.x == b.x && a.y == b.y;
}

void move_by(struct Point *p, int dx, int dy) {    /* pointer: modify caller's. */
    p->x += dx;                                    /* p->x means (*p).x. */
    p->y += dy;
}

int main(void) {
    struct Point p = {.x = 3, .y = 4};             /* designated initialisers. */
    struct Point q = p;                            /* full copy. */
    move_by(&q, 1, 1);                             /* q = (4, 5), p unchanged. */
    printf("(%d, %d) (%d, %d) %d\n", p.x, p.y, q.x, q.y, point_equal(p, q));
    return 0;
}
```

